func positive(raw string) (int, error) {
    n, err := strconv.Atoi(raw)
    if err != nil {
        return 0, fmt.Errorf("parse count: %w", err)
    }
    if n <= 0 {
        return 0, errors.New("count must be positive")
    }
    return n, nil
}

results := make([]int, len(inputs))
var wg sync.WaitGroup
for i, value := range inputs {
    wg.Add(1)
    go func(i, value int) {
        defer wg.Done()
        results[i] = value * 2
    }(i, value)
}
wg.Wait() // Read results only after the writers finish.

func prefix() []byte {
    data := make([]byte, 8<<20)
    // A real program would read data here.
    return data[:16]
}

func detachedPrefix(data []byte) []byte {
    n := min(16, len(data))
    return bytes.Clone(data[:n])
}

