type Order struct { Receipt []byte }
var cache = map[string]*Order{}

func remember(id string, receipt []byte) {
    cache[id] = &Order{Receipt: receipt}
}
// These helpers assume a single owner of cache.
func forget(id string) {
    delete(cache, id)
}

